import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { writeFile } from "node:fs/promises";

async function main() {
  let writerWsData: any;
  let readerWsData: any;

  try {
    const [writerResp, readerResp] = await Promise.all([
      createWorkspace("writer-ws", { credentials: { role: "Editor" } }),
      createWorkspace("reader-ws", { credentials: { role: "ReadOnly" } }),
    ]);

    if (writerResp.error) {
      throw new Error(`Writer workspace creation failed: ${writerResp.error}`);
    }
    if (readerResp.error) {
      throw new Error(`Reader workspace creation failed: ${readerResp.error}`);
    }

    writerWsData = writerResp.data;
    readerWsData = readerResp.data;

    // Validate responses
    if (!writerWsData?.bucket || !writerWsData?.credentials?.accessKeyId || !writerWsData?.credentials?.secretAccessKey) {
      throw new Error("Writer workspace response missing bucket or credentials");
    }
    if (!readerWsData?.bucket || !readerWsData?.credentials?.accessKeyId || !readerWsData?.credentials?.secretAccessKey) {
      throw new Error("Reader workspace response missing bucket or credentials");
    }

    const writerClient = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: writerWsData.credentials.accessKeyId,
        secretAccessKey: writerWsData.credentials.secretAccessKey,
      },
    });

    const readerClient = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: readerWsData.credentials.accessKeyId,
        secretAccessKey: readerWsData.credentials.secretAccessKey,
      },
    });

    let writer_put_ok = false;
    try {
      await writerClient.send(new PutObjectCommand({
        Bucket: writerWsData.bucket,
        Key: "note.txt",
        Body: "hello dual role",
      }));
      writer_put_ok = true;
    } catch (e) {
      console.error("Writer PutObject failed:", e);
      writer_put_ok = false;
    }

    let readonly_put_blocked = false;
    try {
      await readerClient.send(new PutObjectCommand({
        Bucket: readerWsData.bucket,
        Key: "note.txt",
        Body: "should be blocked",
      }));
      readonly_put_blocked = false;
    } catch (e: any) {
      const name = e.name;
      const code = e.Code;
      const status = e.$metadata?.httpStatusCode;

      if (name === "AccessDenied" || code === "AccessDenied" || 
          name === "NotImplemented" || code === "NotImplemented" || 
          status === 403) {
        readonly_put_blocked = true;
      } else {
        console.error("Reader PutObject failed with unexpected error:", e);
        readonly_put_blocked = false;
      }
    }

    const result = {
      writer_bucket: "writer-ws",
      reader_bucket: "reader-ws",
      writer_put_ok,
      readonly_put_blocked,
    };

    await writeFile("/home/user/dual-role/result.json", JSON.stringify(result, null, 2));
    console.log("Result summary written to result.json");

  } finally {
    console.log("Cleaning up workspaces...");
    await Promise.all([
      teardownWorkspace("writer-ws"),
      teardownWorkspace("reader-ws")
    ]).catch(err => console.error("Error during teardown:", err));
    console.log("Cleanup complete.");
  }
}

main().catch(err => {
  console.error("Script failed:", err);
  process.exit(1);
});

import { teardownWorkspace } from "@tigrisdata/agent-kit";

async function cleanup() {
  console.log("Attempting to cleanup existing workspaces...");
  await Promise.all([
    teardownWorkspace("writer-ws"),
    teardownWorkspace("reader-ws")
  ]).catch(err => console.error("Cleanup failed:", err));
  console.log("Cleanup attempt finished.");
}

cleanup();

